public class Load1 {
    public static void main(String[] a) throws Exception {
        System.out.println("1) Class.forName(initialize=false)");
        Class<?> c = Class.forName("Holder", false, Load1.class.getClassLoader());
        System.out.println("   loaded: " + c.getName());
        System.out.println("2) 상수만 읽는다");
        System.out.println("   " + Holder.CONST);
        System.out.println("3) 상수가 아닌 static 을 읽는다");
        System.out.println("   " + Holder.RUNTIME.length() + " chars");
    }
}

